'use strict';
const TEXT_FONTS={sans:{name:'清晰黑体',family:'\"Microsoft YaHei\",\"PingFang SC\",sans-serif'},serif:{name:'书刊宋体',family:'Georgia,\"SimSun\",serif'},longcang:{name:'龙藏手书',family:'LongCang,cursive'},caveat:{name:'Caveat 手写',family:'Caveat,LongCang,cursive'},patrick:{name:'Patrick Hand 手写',family:'\"Patrick Hand\",LongCang,cursive'}};
const textMarkupBase=elementMarkup;
elementMarkup=function(e,s,urls,editing){if(e.kind!=='text')return textMarkupBase(e,s,urls,editing);const text=e.text||'';return `<div class="design-item kind-text${editing?' editable':''}" data-element-id="${esc(e.id)}" style="${elementStyle(e)};font-family:${(TEXT_FONTS[e.typeface]||TEXT_FONTS.longcang).family.replaceAll('"','&quot;')}"><span ${editing?'':'class="typewriter-text" data-typewriter'} data-full-text="${esc(text)}">${editing?esc(text):''}</span>${editing?'<i class="resize-handle" aria-label="调整大小"></i>':''}</div>`;};
const textSelectBase=selectCanvasItem;
selectCanvasItem=function(id){textSelectBase(id);const e=currentPage()?.elements.find(e=>e.id===id);if(e?.kind==='media'){const label=document.createElement('label');label.innerHTML=`照片边框<select id="canvas-photo-border">${[['none','无边框'],['line','细线'],['white','白边'],['polaroid','拍立得'],['rounded','圆角']].map(([k,n])=>`<option value="${k}" ${e.border===k?'selected':''}>${n}</option>`).join('')}</select>`;$('#studio-inspector .section-label').after(label);$('#canvas-photo-border').value=e.border||'none';$('#canvas-photo-border').onchange=ev=>{snapshot();e.border=ev.target.value;studioChanged();paintArtboard();};}if(e?.kind!=='text')return;$('#studio-inspector .section-label').textContent='文本框';const fontLabel=document.createElement('label');fontLabel.innerHTML=`字体<select id="canvas-text-font">${Object.entries(TEXT_FONTS).map(([k,f])=>`<option value="${k}">${f.name}</option>`).join('')}</select>`;$('#studio-inspector .section-label').after(fontLabel);$('#canvas-text-font').value=e.typeface||'longcang';$('#canvas-text-font').onchange=ev=>{snapshot();e.typeface=ev.target.value;studioChanged();paintArtboard();};const label=document.createElement('label');label.innerHTML=`文本内容<textarea id="canvas-text-content" maxlength="10000" rows="6">${esc(e.text||'')}</textarea>`;$('#studio-inspector .section-label').after(label);const input=$('#canvas-text-content');input.onfocus=()=>snapshot();input.oninput=()=>{e.text=input.value;const span=$(`#studio-artboard [data-element-id="${id}"] span`);if(span)span.textContent=e.text;studioChanged();};};
const textStudioBase=openMediaSettings;
openMediaSettings=async function(...args){await textStudioBase(...args);if(!$('#studio-artboard')||$('#studio-add-text'))return;const button=document.createElement('button');button.id='studio-add-text';button.className='outline-btn';button.textContent='＋ 文本框';$('#studio-note-edit').before(button);button.onclick=()=>{snapshot();const e=item('text',5,65,42,28,{text:'',typeface:'longcang',font:2.6,z:30});currentPage().elements.push(e);studioContext.selected=e.id;studioChanged();paintArtboard();$('#canvas-text-content')?.focus();};};

function pagePlaceTitle(s){return `<div class="page-place-title"><b>${esc(s.en||s.name)}</b>${s.en?`<small>${esc(s.name)}</small>`:''}</div>`;}
const titledArtboard=paintArtboard;paintArtboard=function(){titledArtboard();const s=tripById(studioContext?.tid)?.stops.find(s=>s.id===studioContext?.sid);if(s&&$('#studio-artboard')){$('#studio-artboard').insertAdjacentHTML('afterbegin',pagePlaceTitle(s));for(const node of $$('#studio-artboard .design-item')){const e=currentPage().elements.find(e=>e.id===node.dataset.elementId);if(!e||!['media','text'].includes(e.kind))continue;const button=document.createElement('button');button.className='canvas-remove-item';button.textContent='×';button.title=e.kind==='media'?'从此页删除照片':'从此页删除文本框';button.setAttribute('aria-label',button.title);button.onpointerdown=ev=>ev.stopPropagation();button.onclick=ev=>{ev.stopPropagation();snapshot();if(e.kind==='media')s.design.excluded=[...new Set([...(s.design.excluded||[]),e.mediaId])];currentPage().elements=currentPage().elements.filter(x=>x.id!==e.id);studioContext.selected=null;studioChanged();paintArtboard();$('#studio-inspector').innerHTML='<div class="hint">已从此页移除，可撤销；原始素材保留。</div>';};node.append(button);}}};
const titledTyping=prepareTyping;prepareTyping=function(scene){if(scene.type==='spread'){const s=tripById(scene.tid)?.stops.find(s=>s.id===scene.sid);if(s&&!$('#media-viewport .page-place-title'))$('#media-viewport').insertAdjacentHTML('afterbegin',pagePlaceTitle(s));}titledTyping(scene);};

if(!state.settings.handwrittenTextRevision){for(const t of state.trips)for(const s of t.stops)for(const p of s.design?.pages||[])for(const e of p.elements)if(e.kind==='text'&&(!e.typeface||['sans','serif'].includes(e.typeface)))e.typeface='longcang';state.settings.handwrittenTextRevision=1;save();}
